const {contextBridge,ipcRenderer}=require('electron');
const channels=new Set(['playit-state','playit-stop','playit-open','multiplayer-state','server-create','server-start','server-console','server-stop','server-share','server-unshare','friend-save','friend-join','relay-config','aternos-open','onboarding-state','onboarding-update','onboarding-finish','onboarding-reset','auth-diagnostic','auth-diagnostic-copy','vanilla-list','vanilla-install','wardrobe-settings','wardrobe-configure','sharing-install','sharing-server','skin-starter','wearable-remove','wardrobe-export-skin','admin-items','admin-delete','admin-draft-save','admin-draft-load','update-state','update-check','update-download','update-cancel','update-install','update-config','launcher-access','featured-creators','chat-show','chat-hide','chat-bounds','chat-reload','chat-account','chat-signout',"native-client-state","native-client-install","tools-list","tools-run","ready-download","animated-wings-remove","emote-remove","owner-state","admin-rules","admin-rules-copy","wardrobe-remove","admin-texture","admin-voucher","ready-list","ready-install","cloud-state","cloud-auth","cloud-logout","cloud-sync","cloud-restore","cloud-public","admin-publish","voucher-redeem","wardrobe","wardrobe-claim","wardrobe-equip","wardrobe-download","skin-import","skin-remove","skin-preview","account-list","account-switch","minecraft-wardrobe","minecraft-cape","server-copy",'curated','optimization','client-features','client-preset','preferences','state','versions','loaders','create','install','launch','stop','search','content-versions','content-install','pack-download','pack-import','content-list','content-action','worlds','local-import','folder','logs','external','settings','java-select','auth','logout','window']);
contextBridge.exposeInMainWorld('launcher',{
  call:async(channel,payload)=>{if(!channels.has(channel))throw new Error('Unknown request.');const r=await ipcRenderer.invoke(channel,payload);if(!r.ok)throw new Error(r.error);return r.data;},
  on:(channel,fn)=>{if(!['server-event','update','launcher-access','chat-account','progress','busy','game','log','account','auth-error','auth-diagnostic'].includes(channel))throw new Error('Unknown event.');const listener=(_,value)=>fn(value);ipcRenderer.on(channel,listener);return ()=>ipcRenderer.removeListener(channel,listener);}
});
